```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>
#include <algorithm>
#include <climits>

using namespace std;

typedef pair<int, int> pii;
typedef vector<pii> vii;

class Graph {
public:
    unordered_map<int, vii> adjList;
    void addEdge(int u, int v, int w) {
        adjList[u].push_back({v, w});
        adjList[v].push_back({u, w});
    }
    vector<long long> dijkstra(int src, int n) {
        vector<long long> dist(n + 1, LLONG_MAX);
        dist[src] = 0;
        priority_queue<pii, vector<pii>, greater<pii>> pq;
        pq.push({0, src});
        while (!pq.empty()) {
            int u = pq.top().second;
            int d = pq.top().first;
            pq.pop();
            if (d != dist[u]) continue;
            for (auto& edge : adjList[u]) {
                int v = edge.first;
                int w = edge.second;
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push({dist[v], v});
                }
            }
        }
        return dist;
    }
};

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    if (n == 2 && m != 1) {
        cerr << "Error: There should be exactly one road when n is 2." << endl;
        return 1;
    }

    Graph g;
    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        g.addEdge(u, v, w);
    }

    auto distFrom1 = g.dijkstra(1, n);
    auto distFromN = g.dijkstra(n, n);

    for (int i = 0; i < k; ++i) {
        int aj, bj;
        cin >> aj >> bj;

        long long minMaxTime = LLONG_MAX;
        for (int j = 1; j <= n; ++j) {
            long long thuanTime = distFrom1[j] * aj;
            long long dongTime = distFromN[j] * bj;
            long long maxTime = max(thuanTime, dongTime);
            minMaxTime = min(minMaxTime, maxTime);
        }

        cout << minMaxTime << endl;
    }

    return 0;
}
```

