def compute_first_sets(grammar):
    firsts = {symbol: set() for symbol in grammar}
    changed = True

    while changed:
        changed = False
        for symbol in grammar:
            for production in grammar[symbol]:
                if production[0].islower() or production[0] == '$':
                    if production[0] not in firsts[symbol]:
                        firsts[symbol].add(production[0])
                        changed = True
                elif production[0] != 'ε':
                    for token in production:
                        if 'ε' in firsts[token]:
                            firsts[symbol] |= firsts[token] - {'ε'}
                        else:
                            firsts[symbol] |= firsts[token]
                            break
                else:
                    if 'ε' not in firsts[symbol]:
                        firsts[symbol].add('ε')
                        changed = True

    return firsts

def compute_follow_sets(grammar, firsts):
    follows = {symbol: set() for symbol in grammar}
    follows['S'].add('$')

    changed = True
    while changed:
        changed = False
        for symbol in grammar:
            for production in grammar[symbol]:
                for i, token in enumerate(production):
                    if token.isupper():
                        if i+1 < len(production):
                            first_next = firsts[production[i+1]]
                            if 'ε' in first_next:
                                follows[token] |= first_next - {'ε'}
                                follows[token] |= follows[symbol]
                            else:
                                follows[token] |= first_next
                        else:
                            follows[token] |= follows[symbol]
                        if 'ε' in firsts[token]:
                            follows[token] |= follows[symbol]
                            changed = True

    return follows

def build_ll1_table(grammar, firsts, follows):
    table = {}
    for symbol in grammar:
        table[symbol] = {}
        for production in grammar[symbol]:
            for token in firsts[symbol]:
                if token != 'ε':
                    table[symbol][token] = production
            if 'ε' in firsts[symbol]:
                for token in follows[symbol]:
                    table[symbol][token] = production

    return table

def print_table(table):
    print("\nLL(1) Parsing Table:")
    for key, value in table.items():
        print(f"{key}: {value}")

def parse_input(input_string, table, firsts, follows):
    stack = ['$', 'S']
    input_index = 0
    output = []

    while stack:
        top = stack.pop()
        current_input = input_string[input_index]

        if current_input in firsts[top] or (top == 'ε' and current_input in follows[top]):
            if top == 'ε':
                pass
            elif top.isupper():
                if current_input in table[top]:
                    production = table[top][current_input]
                    for token in reversed(production):
                        if token != 'ε':
                            stack.append(token)
                else:
                    raise ValueError(f"Error at position {input_index}: Expected {follows[top]} but got {current_input}")
            else:
                output.append(top)
                input_index += 1
        else:
            raise ValueError(f"Error at position {input_index}: Expected {firsts[top]} but got {current_input}")

    return output

